<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>GALAGA</title>
<style>
  html,body{margin:0;height:100%;background:#000;overflow:hidden}
  #wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
  canvas{image-rendering:pixelated;image-rendering:crisp-edges;background:#000}
</style>
</head>
<body>
<div id="wrap"><canvas id="cv" width="224" height="288"></canvas></div>
<script>
'use strict';
/* =====================================================================
   GALAGA clone - single file.  Internal resolution 224x288 (arcade 3:4),
   fixed-timestep simulation at 60Hz, everything drawn/synthesized in code.
   ===================================================================== */

/* ---------------- basics / canvas scaling ---------------- */
const W=224, H=288, CX=112, STEP=1/60;
const cv=document.getElementById('cv'), ctx=cv.getContext('2d');
function resize(){
  const s=Math.max(1,Math.floor(Math.min(innerWidth/W, innerHeight/H)));
  cv.style.width=(W*s)+'px'; cv.style.height=(H*s)+'px';
}
addEventListener('resize',resize); resize();

/* ---------------- pixel-art sprites (defined as data) ---------------- */
function mk(rows,pal){
  const w=rows[0].length,h=rows.length;
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  const x=c.getContext('2d');
  for(let j=0;j<h;j++)for(let i=0;i<w;i++){
    const col=pal[rows[j][i]];
    if(col){x.fillStyle=col;x.fillRect(i,j,1,1);}
  }
  return c;
}
const PLAYER_ROWS=[
"......W......",
"......W......",
".....WWW.....",
".....WRW.....",
"....WWWWW....",
"....WWBWW....",
"...WWWWWWW...",
"..WWWWBWWWW..",
".WWWWWBWWWWW.",
"WWWWWWBWWWWWW",
"WWWWWWBWWWWWW",
"WW..WWWWW..WW",
"W...WWWWW...W",
"W....WWW....W"];
const ZAKO1=[
".BB......BB.",
".BBB....BBB.",
"..YBBBBBBY..",
"...YYYYYY...",
"..YYbYYbYY..",
"..YYYYYYYY..",
"...YYYYYY...",
"....Y..Y....",
"....B..B...."];
const ZAKO2=[
"............",
"..YBBBBBBY..",
"...YYYYYY...",
"BB.YYbbYY.BB",
"BB.YYYYYY.BB",
"..YYYYYYYY..",
"...YYYYYY...",
"....Y..Y....",
"....B..B...."];
const GOEI1=[
".RR......RR.",
".RRR....RRR.",
".RRRR..RRRR.",
"..RRRRRRRR..",
"...RWRRWR...",
"...RRRRRR...",
"....RRRR....",
"...RR..RR...",
"....R..R...."];
const GOEI2=[
"............",
"..RR....RR..",
".RRRR..RRRR.",
"..RRRRRRRR..",
"...RWRRWR...",
"...RRRRRR...",
"....RRRR....",
"...RR..RR...",
"....R..R...."];
const BOSS1=[
"..GGGGGGGG..",
".GGGGGGGGGG.",
"GGGWWGGGGWWGGG",
"GGGGGGGGGGGGGG",
".GGGGGGGGGG.",
"..GGGGGGGG..",
"...GGGGGG...",
"..GG.GGGG.GG..",
"..G...GG...G.."];
const BOSS2=[
"..............",
".GG.GGGGGG.GG.",
"GGGWWGGGGWWGGG",
"GGGGGGGGGGGGGG",
".GGGGGGGGGG.",
"..GGGGGGGG..",
"...GGGGGG...",
"..GG.GGGG.GG..",
"..G...GG...G.."];
const FLAG=[
"RRRRRR...",
"RRRRRWR..",
"RRRRRR...",
"R........",
"R........",
"R........",
"R........",
"R........"];
const SPR={
  player   : mk(PLAYER_ROWS,{W:'#ffffff',R:'#ff2828',B:'#40d0ff'}),
  playerRed: mk(PLAYER_ROWS,{W:'#ff5858',R:'#ffe0e0',B:'#ff9090'}),
  zako:[mk(ZAKO1,{Y:'#ffd838',B:'#3050ff',b:'#101848'}),
        mk(ZAKO2,{Y:'#ffd838',B:'#3050ff',b:'#101848'})],
  goei:[mk(GOEI1,{R:'#ff3838',W:'#ffffff'}), mk(GOEI2,{R:'#ff3838',W:'#ffffff'})],
  boss:[mk(BOSS1,{G:'#40e040',W:'#ffffff'}), mk(BOSS2,{G:'#40e040',W:'#ffffff'})],
  bossHit:[mk(BOSS1,{G:'#5858ff',W:'#ffffff'}), mk(BOSS2,{G:'#5858ff',W:'#ffffff'})],
  flag: mk(FLAG,{R:'#ff3030',W:'#ffffff'})
};
function sprFor(e){
  const f=(e.animT*6|0)%2;
  if(e.type==='zako')return SPR.zako[f];
  if(e.type==='goei')return SPR.goei[f];
  if(e.type==='boss')return e.hp===1?SPR.bossHit[f]:SPR.boss[f];
  return SPR.playerRed;
}

/* ---------------- Web Audio (all sounds synthesized) ---------------- */
let AC=null, master=null, muted=false, beamSnd=null;
function audioInit(){
  if(AC)return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=0.35; master.connect(AC.destination);
  }catch(e){}
}
function tone(f,d,type,v,slide,delay){
  if(!AC||muted)return;
  const t=AC.currentTime+(delay||0);
  const o=AC.createOscillator(),g=AC.createGain();
  o.type=type||'square';
  o.frequency.setValueAtTime(f,t);
  if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),t+d);
  g.gain.setValueAtTime(v||0.2,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+d);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t+d+0.02);
}
function noiseBurst(d,v,f0,f1){
  if(!AC||muted)return;
  const t=AC.currentTime,n=(AC.sampleRate*d)|0;
  const buf=AC.createBuffer(1,n,AC.sampleRate),ch=buf.getChannelData(0);
  for(let i=0;i<n;i++)ch[i]=Math.random()*2-1;
  const s=AC.createBufferSource(); s.buffer=buf;
  const flt=AC.createBiquadFilter(); flt.type='lowpass';
  flt.frequency.setValueAtTime(f0,t); flt.frequency.exponentialRampToValueAtTime(Math.max(40,f1),t+d);
  const g=AC.createGain(); g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(0.001,t+d);
  s.connect(flt); flt.connect(g); g.connect(master); s.start(t);
}
const sndShot =()=>tone(1150,0.09,'square',0.10,240);
const sndHit  =()=>tone(320,0.08,'triangle',0.22,90);
const sndDie  =()=>{noiseBurst(0.18,0.30,1400,180);tone(210,0.14,'square',0.10,60);};
const sndBossHit=()=>tone(1500,0.07,'square',0.16,800);
const sndPlayerDie=()=>{noiseBurst(0.6,0.5,900,70);tone(170,0.55,'sawtooth',0.14,40);};
const sndCapture=()=>tone(650,0.7,'sawtooth',0.14,120);
const sndDock =()=>{tone(523,0.08,'square',0.15);tone(784,0.08,'square',0.15,0,0.09);tone(1046,0.15,'square',0.15,0,0.18);};
const sndJingle=()=>{[[523,.09],[659,.09],[784,.09],[1046,.2]].forEach((n,i)=>tone(n[0],n[1],'square',0.16,0,i*0.11));};
const sndWave =()=>{for(let i=0;i<4;i++)tone(880,0.05,'square',0.12,0,i*0.07);};
const sndBonus=()=>{[659,784,988,1318].forEach((f,i)=>tone(f,0.1,'square',0.16,0,i*0.1));};
function startBeamSnd(){
  if(!AC||muted||beamSnd)return;
  const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();
  o.type='triangle'; o.frequency.value=520;
  l.type='sine'; l.frequency.value=7; lg.gain.value=180;
  l.connect(lg); lg.connect(o.frequency);
  g.gain.value=0.10;
  o.connect(g); g.connect(master); o.start(); l.start();
  beamSnd={o,l,g};
}
function stopBeamSnd(){
  if(!beamSnd)return;
  try{beamSnd.g.gain.value=0;beamSnd.o.stop();beamSnd.l.stop();}catch(e){}
  beamSnd=null;
}

/* ---------------- scrolling twinkling starfield ---------------- */
const STAR_COLS=['#ffffff','#88ffff','#ff88ff','#ffff88','#ff8888'];
const stars=[];
for(let i=0;i<70;i++)stars.push({x:Math.random()*W,y:Math.random()*H,
  s:5+Math.random()*24,c:STAR_COLS[i%5],p:Math.random()*6.283});
function updateStars(dt){
  for(const s of stars){ s.y+=s.s*dt; if(s.y>H){s.y=-1;s.x=Math.random()*W;} }
}
function drawStars(){
  for(const s of stars){
    ctx.globalAlpha=0.35+0.65*Math.abs(Math.sin(game.time*2+s.p));
    ctx.fillStyle=s.c; ctx.fillRect(s.x|0,s.y|0,1,1);
  }
  ctx.globalAlpha=1;
}

/* ---------------- path helpers (Catmull-Rom -> cubic bezier chain) ---- */
function chainFromWaypoints(pts){
  const c=[pts[0].slice()];
  for(let i=0;i<pts.length-1;i++){
    const p0=pts[Math.max(0,i-1)],p1=pts[i],p2=pts[i+1],p3=pts[Math.min(pts.length-1,i+2)];
    c.push([p1[0]+(p2[0]-p0[0])/6,p1[1]+(p2[1]-p0[1])/6]);
    c.push([p2[0]-(p3[0]-p1[0])/6,p2[1]-(p3[1]-p1[1])/6]);
    c.push(p2.slice());
  }
  return c;
}
function pathPoint(ch,t){
  const segs=(ch.length-1)/3;
  let s=Math.min(Math.floor(t*segs),segs-1),u=t*segs-s;
  const p=ch.slice(s*3,s*3+4);
  const m=1-u;
  return [ m*m*m*p[0][0]+3*m*m*u*p[1][0]+3*m*u*u*p[2][0]+u*u*u*p[3][0],
           m*m*m*p[0][1]+3*m*m*u*p[1][1]+3*m*u*u*p[2][1]+u*u*u*p[3][1] ];
}
/* entry path templates (end at [0,0]; final pos = point + slot) */
const ENTRY_WP=[
 [[-30,200],[30,245],[110,240],[155,195],[125,130],[50,115],[35,170],[0,0]],
 [[254,200],[194,245],[114,240],[69,195],[99,130],[174,115],[189,170],[0,0]],
 [[60,-30],[35,55],[90,115],[165,125],[175,65],[115,15],[0,0]],
 [[-30,120],[60,155],[140,120],[195,165],[150,225],[70,205],[0,0]]];
const ENTRY_CHAIN=ENTRY_WP.map(chainFromWaypoints);
/* challenging-stage loop patterns (absolute coords) */
const CHAL_WP=[
 [[-30,70],[60,130],[140,60],[220,120],[262,80]],
 [[254,70],[164,130],[84,60],[4,120],[-38,80]],
 [[-30,235],[70,175],[160,235],[262,165]],
 [[112,-30],[55,80],[165,140],[75,225],[140,320]],
 [[254,235],[154,175],[64,235],[-38,165]]];
const CHAL_CHAIN=CHAL_WP.map(chainFromWaypoints);

/* ---------------- game state ---------------- */
const game={
  state:'title', time:0, stage:1, score:0,
  hi:parseInt(localStorage.getItem('galaga_hi')||'0',10)||0,
  lives:2, nextExtra:20000,
  shotsFired:0, shotsHit:0,
  formationT:0, formationComplete:false,
  diveT:3, fireT:2,
  introT:0, readyT:0, overT:0, resT:0, clearT:0,
  paused:false, chal:null
};
const player={x:CX,state:'alive',dual:false,inv:0,dyingT:0,respawnT:0,capT:0,capBoss:null};
let enemies=[], shots=[], ebullets=[], expls=[], popups=[], freed=null;
const keys={};

function addScore(n){
  game.score+=n;
  if(game.score>game.hi)game.hi=game.score;
  while(game.score>=game.nextExtra){ game.lives++; game.nextExtra+=70000; }
}
function addExplosion(x,y,big){ expls.push({x,y,t:0,big:!!big}); }
function addPopup(x,y,text,color){ popups.push({x,y,text,color:color||'#fff',t:0}); }

/* ---------------- formation layout ---------------- */
function slotXY(row,col){
  let x;
  if(row===0)x=CX+(col-1.5)*16;
  else if(row<3)x=CX+(col-3.5)*16;
  else x=CX+(col-4.5)*16;
  return {x,y:42+row*16};
}
function makeEnemy(type,row,col){
  const s=slotXY(row,col);
  return {type,row,col,slot:s,x:s.x,y:s.y,state:'formation',
    animT:Math.random(),hp:type==='boss'?2:1,
    path:null,pathT:0,dur:1,fireT:0,delay:0,
    beamT:0,beamX:0,escorts:[],captive:null};
}
/* standard formation: 4 boss / 16 goei / 20 zako, entering in groups of 4 */
function buildStage(){
  enemies=[]; shots=[]; ebullets=[]; expls=[]; popups=[]; freed=null;
  stopBeamSnd();
  game.formationT=0; game.formationComplete=false;
  game.diveT=2.5; game.fireT=2;
  const order=[];
  for(let c=0;c<4;c++)order.push(['boss',0,c]);
  for(let r=1;r<=2;r++)for(let c=0;c<8;c++)order.push(['goei',r,c]);
  for(let r=3;r<=4;r++)for(let c=0;c<10;c++)order.push(['zako',r,c]);
  for(let g=0;g<order.length/4;g++){
    const ch=ENTRY_CHAIN[g%4];
    for(let m=0;m<4;m++){
      const [t,r,c]=order[g*4+m];
      const e=makeEnemy(t,r,c);
      e.state='entry'; e.path=ch; e.pathT=0; e.dur=3.2;
      e.delay=g*1.05+m*0.3;
      enemies.push(e);
    }
  }
}
function slotPos(e){
  const sway=Math.sin(game.formationT*1.1)*10;
  const br=game.formationComplete?1+0.05*Math.sin(game.formationT*0.9):1;
  return {x:CX+(e.slot.x-CX)*br+sway, y:e.slot.y};
}

/* ---------------- challenging stage ---------------- */
function isChalStage(n){ return n>=3 && (n-3)%4===0; }
function startChal(){
  enemies=[]; shots=[]; ebullets=[]; freed=null; stopBeamSnd();
  game.chal={wave:0,waveLeft:0,waveHits:0,hits:0,bonus:0,
             spawnT:0.5,cool:0,types:['zako','zako','zako','zako','goei','goei','boss','boss']};
  game.state='chal';
}
function spawnChalWave(){
  const c=game.chal;
  c.wave++; c.waveHits=0; c.waveLeft=8;
  const ch=CHAL_CHAIN[(c.wave-1)%CHAL_CHAIN.length];
  for(let i=0;i<8;i++){
    const e=makeEnemy(c.types[i],0,0);
    e.state='chal'; e.path=ch; e.pathT=-i*0.06; e.dur=4.6;
    e.x=-40; e.y=-40;
    enemies.push(e);
  }
  sndWave();
}
function chalWaveDone(){
  const c=game.chal;
  if(c.waveHits>=8){ c.bonus+=1000; addScore(1000); addPopup(CX,140,'GREAT!  1000','#40ff40'); sndBonus(); }
  if(c.wave>=5) endChal();
  else { c.cool=1.6; game.state='chalWait'; }
}
function endChal(){
  const c=game.chal;
  if(c.hits>=40){ c.bonus+=10000; addScore(10000); }
  game.state='chalEnd'; game.resT=4.5;
}

/* ---------------- stage / flow control ---------------- */
function startGame(){
  game.score=0; game.lives=2; game.nextExtra=20000;
  game.shotsFired=0; game.shotsHit=0; game.stage=1;
  player.x=CX; player.dual=false; player.state='alive'; player.inv=2;
  startStage();
}
function startStage(){
  if(isChalStage(game.stage)){
    game.state='intro'; game.introT=2.2; sndJingle();
    startChal(); game.state='intro';
  }else{
    buildStage();
    game.state='intro'; game.introT=2; sndJingle();
  }
}
function beginReady(){ game.state='ready'; game.readyT=1.4; }
function gameOver(){
  localStorage.setItem('galaga_hi',String(game.hi));
  game.state='over'; game.overT=2.6; stopBeamSnd();
}

/* ---------------- player helpers ---------------- */
function fire(){
  if(player.state!=='alive')return;
  if(shots.length>=2)return;                 /* arcade limit: 2 shots on screen */
  game.shotsFired++;
  if(player.dual){ shots.push({x:player.x-7,y:player.y-8}); shots.push({x:player.x+7,y:player.y-8}); }
  else shots.push({x:player.x,y:player.y-8});
  sndShot();
}
function playerHit(){
  if(player.inv>0||player.state!=='alive')return;
  addExplosion(player.x,player.y,true); sndPlayerDie();
  player.state='dying'; player.dyingT=0.9;
}
function loseShip(){
  game.lives--;
  player.dual=false;
  if(game.lives<0){ gameOver(); return; }
  ebullets=[];
  player.x=CX; player.state='gone'; player.respawnT=0.8;
  beginReady();
}

/* ---------------- enemy behaviour ---------------- */
function makeDivePath(e){
  const px=player.x, dir=e.x<CX?-1:1;
  return chainFromWaypoints([
    [e.x,e.y],[e.x+dir*20,e.y+25],[e.x+dir*32,e.y+55],
    [px+dir*26,170],[px,225],[px+(Math.random()*60-30),H+30]]);
}
function makeBeamPath(e){
  const px=player.x, dir=e.x<CX?-1:1;
  return chainFromWaypoints([[e.x,e.y],[e.x+dir*25,e.y+30],[px,120],[e.x,150]]);
}
function startDive(e,shiftX,dur){
  e.state='dive'; e.path=makeDivePath(e); if(shiftX)
    e.path=e.path.map(p=>[p[0]+shiftX,p[1]]);
  e.pathT=0; e.dur=Math.max(1.4,dur||2.3-game.stage*0.05); e.fireT=0.3+Math.random()*0.5;
}
function startBeamDive(b){
  b.state='dive'; b.path=makeBeamPath(b); b.pathT=0; b.dur=1.8; b.beamT=0;
  b.fireT=0.4;
}
function pickFormation(pred){
  const f=enemies.filter(e=>e.state==='formation'&&pred(e));
  return f.length?f[(Math.random()*f.length)|0]:null;
}
function launchDive(){
  /* occasionally a Boss Galaga dives (sometimes with Goei escorts, sometimes tractor beam) */
  const bossChance=game.stage>=2&&Math.random()<0.3;
  const boss=bossChance?pickFormation(e=>e.type==='boss'):null;
  if(boss){
    if(game.stage>=2&&Math.random()<0.45&&!boss.captive&&!enemies.some(e=>e.captive)){
      startBeamDive(boss); return;
    }
    const dur=Math.max(1.4,2.3-game.stage*0.05);
    startDive(boss,0,dur);
    const near=enemies.filter(e=>e.state==='formation'&&e.type==='goei')
      .sort((a,b)=>Math.abs(a.slot.x-boss.slot.x)-Math.abs(b.slot.x-boss.slot.x));
    const n=Math.min(2,(Math.random()*3)|0);
    boss.escorts=[];
    for(let i=0;i<n&&i<near.length;i++){
      const esc=near[i];
      startDive(esc,esc.slot.x-boss.slot.x,dur);
      esc.escortOf=boss; boss.escorts.push(esc);
    }
    return;
  }
  /* normal divers: 1 (2 in later stages) */
  const n=(game.stage>=4&&Math.random()<0.4)?2:1;
  for(let i=0;i<n;i++){
    const e=pickFormation(x=>x.type!=='boss'||Math.random()<0.15);
    if(e)startDive(e,0);
  }
}
function enemyShoot(e,aimed){
  if(ebullets.length>10)return;
  const sp=80+Math.min(game.stage,8)*6;
  let vx=0,vy=sp;
  if(aimed){
    const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;
    vx=dx/d*sp; vy=dy/d*sp;
  }
  ebullets.push({x:e.x,y:e.y+5,vx,vy});
}
function startCapture(boss){
  player.state='capturing'; player.capT=0; player.capBoss=boss;
  stopBeamSnd(); sndCapture();
}
function killEnemy(e,byPlayer){
  e.state='dead';
  addExplosion(e.x,e.y,false);
  if(e.captive){                       /* boss held a captured fighter */
    const diving=(e.beamActive||e.state==='dead'&&wasDiving(e));
    e.captive=null;
    if(byPlayer&&wasDiving(e)){
      freed={x:e.x,y:e.y,t:0};         /* freed fighter flies down and docks */
      addPopup(e.x,e.y-14,'RESCUED!','#40ffff');
    }else{
      const cf=makeEnemy('captive',0,0);
      cf.x=e.x; cf.y=e.y-12; cf.state='dive'; cf.dual=false;
      cf.path=makeDivePath(cf); cf.pathT=0; cf.dur=2.2; cf.fireT=0.3;
      enemies.push(cf);                /* captive turns hostile, does not return */
    }
    sndPlayerDie();
  }
  if(e.escortOf){
    const b=e.escortOf;
    b.escorts=b.escorts.filter(x=>x!==e);
  }
}
/* remember dive state before we overwrite it */
let _diveFlag=false;
function wasDiving(e){return _diveFlag;}
function scoreKill(e){
  _diveFlag=(e.state==='dive'||e.state==='beam');
  const diving=_diveFlag;
  let pts=0;
  if(e.type==='zako')pts=diving?100:50;
  else if(e.type==='goei')pts=diving?160:80;
  else if(e.type==='boss'){
    if(diving){
      const esc=e.escorts.filter(a=>a.state==='dive'||a.state==='beam').length;
      pts=[400,800,1600][Math.min(esc,2)];
    }else pts=150;
  }
  if(e.type==='captive')pts=0;
  if(game.state==='chal')pts=100;
  if(pts)addScore(pts);
  if(e.type==='boss'&&diving)addPopup(e.x,e.y-12,String(pts),'#ffff40');
}

/* ---------------- main update ---------------- */
function updateEnemies(dt){
  let anyForming=false;
  for(const e of enemies){
    e.animT+=dt;
    if(e.state==='entry'){
      anyForming=true;
      if(e.delay>0){e.delay-=dt;continue;}
      e.pathT+=dt/e.dur;
      if(e.pathT>=1){e.state='formation';e.path=null;}
      else{
        const p=pathPoint(e.path,Math.min(e.pathT,1)),s=slotPos(e);
        e.x=p[0]+s.x; e.y=p[1]+s.y;
        if(Math.random()<dt*0.04)enemyShoot(e,true);   /* may fire while entering */
      }
