      const s=slotPos(e); e.x=s.x; e.y=s.y;
      if(e.captive)e.captive.animT+=0; /* captive uses boss animT */
    }else if(e.state==='dive'){
      e.pathT+=dt/e.dur;
      if(e.pathT>=1){                       /* left bottom: re-enter from top */
        e.state='return';
        e.x=Math.max(16,Math.min(W-16,e.slot.x+(Math.random()*40-20)));
        e.y=-14;
      }else{
        const p=pathPoint(e.path,Math.min(e.pathT,1));
        e.x=p[0]; e.y=p[1];
        e.fireT-=dt;
        if(e.fireT<=0&&e.y>10&&e.y<H-40){enemyShoot(e,true);e.fireT=0.5+Math.random()*0.9;}
      }
      if(e.captive){
        e.fireT-=dt*0.5;
        if(e.fireT<=0&&Math.random()<0.5){
          ebullets.push({x:e.x,y:e.y-8,vx:0,vy:110});e.fireT=0.9;
        }
      }
    }else if(e.state==='beam'){
      e.beamT-=dt;
      if(e.beamT<=0){ e.beamActive=false; stopBeamSnd(); e.state='return'; }
    }else if(e.state==='return'){
      const tx=e.slot.x,ty=e.slot.y-30;
      const dx=tx-e.x,dy=ty-e.y,d=Math.hypot(dx,dy);
      const sp=95*dt;
      if(d<sp){e.x=tx;e.y=ty;e.state='home';}
      else{e.x+=dx/d*sp;e.y+=dy/d*sp;}
    }else if(e.state==='home'){
      const s=slotPos(e);
      const dx=s.x-e.x,dy=s.y-e.y,d=Math.hypot(dx,dy);
      const sp=120*dt;
      if(d<sp){e.x=s.x;e.y=s.y;e.state='formation';}
      else{e.x+=dx/d*sp;e.y+=dy/d*sp;}
    }else if(e.state==='chal'){
      e.pathT+=dt/e.dur;
      if(e.pathT>=1){e.state='escaped';}
      else if(e.pathT>=0){const p=pathPoint(e.path,e.pathT);e.x=p[0];e.y=p[1];}
