    if(player.inv>0)player.inv-=dt;
    const sp=130*dt;
    if(keys.left)player.x-=sp;
    if(keys.right)player.x+=sp;
    player.x=Math.max(10,Math.min(W-10,player.x));
    if(keys.fire)fire();
  }else if(player.state==='dying'){
    player.dyingT-=dt;
    if(player.dyingT<=0)loseShip();
  }else if(player.state==='gone'){
    player.respawnT-=dt;
    if(player.respawnT<=0){player.state='alive';player.inv=1.5;}
  }else if(player.state==='capturing'){
    const b=player.capBoss;
    player.capT+=dt;
    const k=Math.min(1,player.capT/1.1);
    player.x+=(b.x-player.x)*Math.min(1,dt*6);
    player.y+=(b.y+14-player.y)*Math.min(1,dt*6);
    if(k>=1){
      b.captive=true; b.state='return'; b.beamActive=false; stopBeamSnd();
      player.state='gone';
      addPopup(b.x,b.y,'CAPTURED!','#ff4040');
      loseShip();
    }
  }
  /* --- shots --- */
  for(const s of shots)s.y-=300*dt;
  shots=shots.filter(s=>s.y>-8);
  for(const b of ebullets){b.x+=b.vx*dt;b.y+=b.vy*dt;}
  ebullets=ebullets.filter(b=>b.x>-8&&b.x<W+8&&b.y>-8&&b.y<H+8);
  /* --- enemies --- */
  updateEnemies(dt);
  /* --- dive scheduling (never while player dead/respawning) --- */
  if(player.state==='alive'&&game.formationComplete){
    game.diveT-=dt;
    if(game.diveT<=0){
      launchDive();
      const base=Math.max(0.7,2.6-game.stage*0.16-Math.min(1,enemies.length<10?0.6:0));
      game.diveT=base+Math.random()*base;
    }
  }
  /* --- formation firing --- */
  game.fireT-=dt;
  if(game.fireT<=0){
    const e=pickFormation(x=>x.row>=2);
    if(e&&player.state==='alive')enemyShoot(e,game.stage>=3&&Math.random()<0.5);
    game.fireT=Math.max(0.45,1.9-game.stage*0.12)+Math.random()*0.9;
  }
  /* --- tractor beams --- */
  let anyBeam=false;
  for(const e of enemies){
    if(e.state==='dive'&&e.pathT>=1&&e.beamT===0&&e.path&&e.path[0][1]===e.path[e.path.length-1][1]&&false){}
    if(e.state==='dive'&&e.beamPending){
      e.beamPending=false; e.state='beam'; e.beamT=3.2; e.beamActive=true;
      e.beamX=e.x; startBeamSnd();
    }
    if(e.state==='beam'){
      anyBeam=true;
      e.x=e.beamX+Math.sin(game.time*3)*2;
      if(e.beamT<2.7&&e.beamT>0.4&&player.state==='alive'&&player.inv<=0){
        const y0=e.y+6,y1=H-16;
        if(player.y>y0){
          const f=Math.min(1,(player.y-y0)/(y1-y0)),hw=4+26*f;
          if(Math.abs(player.x-e.x)<hw){
