  }
  if(!anyBeam)stopBeamSnd();
  /* mark beam bosses (dive path that ends mid-screen) */
  for(const e of enemies)
    if(e.state==='dive'&&e.beamWant&&e.pathT>=1){e.beamWant=false;e.beamPending=true;}
  /* --- freed fighter docking --- */
  if(freed){
    freed.t+=dt;
    freed.y+=70*dt;
    freed.x+=(player.x+(player.dual?7:0)-freed.x)*Math.min(1,dt*3);
    if(freed.y>=player.y){
      if(player.state==='alive'&&!player.dual){
        player.dual=true; addPopup(player.x,player.y-16,'DUAL FIGHTER!','#40ffff'); sndDock();
      }
      freed=null;
    }
  }
  /* --- collisions: player shots vs enemies / enemy bullets --- */
  for(const s of shots){
    for(const e of enemies){
      if(e.state==='dead'||e.state==='escaped')continue;
      if(e.state==='chal'===false&&e.state==='entry'&&e.delay>0)continue;
      if(e.pathT<0)continue;
      const hw=e.type==='boss'?7:6;
      if(Math.abs(s.x-e.x)<=hw&&Math.abs(s.y-e.y)<=6){
        s.dead=true; game.shotsHit++;
        if(e.type==='boss'&&e.hp===2){ e.hp=1; sndBossHit(); }
        else{ scoreKill(e); sndDie(); killEnemy(e,true); }
        break;
      }
    }
    if(!s.dead)for(const b of ebullets){
      if(Math.abs(s.x-b.x)<3&&Math.abs(s.y-b.y)<4){s.dead=true;b.dead=true;break;}
    }
  }
  shots=shots.filter(s=>!s.dead);
  ebullets=ebullets.filter(b=>!b.dead);
  /* --- collisions: enemy bullets / bodies vs player --- */
  if(player.state==='alive'&&player.inv<=0){
    const hitHalf=x=>{
      if(!player.dual)return Math.abs(x-player.x)<=4;
      return Math.abs(x-(player.x-7))<=4||Math.abs(x-(player.x+7))<=4;
    };
    for(const b of ebullets){
      if(b.y>player.y-7&&b.y<player.y+7&&hitHalf(b.x)){
        b.dead=true;
        if(player.dual){                            /* only the hit half is lost */
