          addExplosion(player.x+side*7,player.y,false);
          player.dual=false; player.inv=1.2; sndPlayerDie();
        }else playerHit();
        break;
      }
    }
    ebullets=ebullets.filter(b=>!b.dead);
    if(player.state==='alive')for(const e of enemies){
      if(e.state==='dead'||e.state==='escaped')continue;
      if(e.pathT!==undefined&&e.pathT<0)continue;
      if(e.state==='entry'&&e.delay>0)continue;
      const hw=(e.type==='boss'?7:6)+4;
      const near=player.dual?
        (Math.abs(e.x-(player.x-7))<hw||Math.abs(e.x-(player.x+7))<hw):
        Math.abs(e.x-player.x)<hw;
      if(near&&Math.abs(e.y-player.y)<10){
        scoreKill(e); sndDie(); killEnemy(e,false);
        playerHit();
        break;
      }
    }
  }
  enemies=enemies.filter(e=>e.state!=='dead'&&e.state!=='escaped');
  /* --- stage clear --- */
  if(enemies.length===0&&player.state!=='capturing'){
    game.clearT+=dt;
    if(game.clearT>1.4){
      game.clearT=0; game.stage++;
      localStorage.setItem('galaga_hi',String(game.hi));
      startStage();
    }
  }else game.clearT=0;
}
