/* ---------------- global update ---------------- */
function update(dt){
  game.time+=dt;
  updateStars(dt);
  for(const x of expls)x.t+=dt;
  expls=expls.filter(x=>x.t<(x.big?0.55:0.38));
  for(const p of popups){p.t+=dt;p.y-=8*dt;}
  popups=popups.filter(p=>p.t<1.6);
  switch(game.state){
    case 'title': break;
    case 'intro':
      game.introT-=dt;
      if(game.introT<=0){
        if(game.chal&&game.stage&&isChalStage(game.stage)&&enemies.length===0&&game.chal.wave===0)game.state='chal';
        else beginReady();
      }
      break;
    case 'ready':
      game.readyT-=dt;
      if(game.readyT<=0){game.state='play';player.state='alive';player.inv=1.2;}
      break;
    case 'play': if(!game.paused)updatePlay(dt); break;
    case 'chal': if(!game.paused)updateChal(dt); break;
    case 'chalWait':
      if(!game.paused){
        game.chal.cool-=dt;
        if(game.chal.cool<=0){spawnChalWave();game.state='chal';}
      }
      break;
    case 'chalEnd':
      game.resT-=dt;
      if(game.resT<=0){game.stage++;startStage();}
      break;
    case 'over':
      game.overT-=dt;
      if(game.overT<=0)game.state='results';
      break;
    case 'results': break;
  }
}

